"use client";

import { useState, useRef, useEffect } from "react";
import { 
  Send, UploadCloud, FileText, Leaf, Loader2, Info, 
  MessageSquare, Bot, User, CheckCircle2, Sparkles, 
  Terminal, Database
} from "lucide-react";

type Message = {
  role: "user" | "bot";
  content: string;
};

export default function Home() {
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [uploadedFileName, setUploadedFileName] = useState<string | null>(null);
  const [chatMode, setChatMode] = useState<"simple" | "pdf">("simple");
  
  const messagesEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsUploading(true);
    const formData = new FormData();
    formData.append("file", file);

    try {
      const res = await fetch("http://127.0.0.1:8000/upload-pdf/", {
        method: "POST",
        body: formData,
      });
      if (res.ok) {
        setUploadedFileName(file.name);
        setChatMode("pdf");
        setMessages((prev) => [
          ...prev, 
          { role: "bot", content: `System updated. Vector context loaded from **${file.name}**. I am now querying against this document's specific ESG metrics.` }
        ]);
      }
    } catch (error) {
      console.error(error);
    } finally {
      setIsUploading(false);
    }
  };

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || isLoading) return;

    const userMessage = input;
    setInput("");
    setMessages((prev) => [...prev, { role: "user", content: userMessage }]);
    setIsLoading(true);

    const formData = new FormData();
    formData.append("question", userMessage);

    const endpoint = chatMode === "pdf" && uploadedFileName
        ? "http://127.0.0.1:8000/ask-question/"
        : "http://127.0.0.1:8000/ask-simple/";

    try {
      const res = await fetch(endpoint, { method: "POST", body: formData });
      const data = await res.json();
      if (res.ok) setMessages((prev) => [...prev, { role: "bot", content: data.answer }]);
    } catch (error) {
      setMessages((prev) => [...prev, { role: "bot", content: "Error: Neural link disconnected. Check backend server." }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex h-screen bg-[#09090b] text-slate-300 font-sans selection:bg-emerald-500/30 overflow-hidden">
      
      {/* 🌑 ULTRA-SLEEK SIDEBAR */}
      <div className="w-[300px] bg-[#0c0c0e] border-r border-white/5 flex flex-col z-20 relative">
        
        {/* Logo Area */}
        <div className="p-8 flex items-center gap-4">
          <div className="w-10 h-10 bg-gradient-to-br from-emerald-400 to-teal-600 rounded-lg flex items-center justify-center text-white shadow-[0_0_30px_rgba(16,185,129,0.2)]">
            <Terminal size={20} strokeWidth={2} />
          </div>
          <div>
            <h1 className="text-xl font-bold text-white tracking-tight">EcoBot</h1>
            <div className="flex items-center gap-2 mt-0.5">
              <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></span>
              <span className="text-[10px] text-emerald-500 font-mono tracking-widest uppercase">System Online</span>
            </div>
          </div>
        </div>

        <nav className="flex-1 px-4 space-y-2 mt-4">
          <p className="text-[11px] font-semibold text-slate-500 uppercase tracking-widest px-4 mb-4">Query Modes</p>
          
          <button onClick={() => setChatMode("simple")} className={`group w-full p-4 rounded-xl flex items-center gap-4 transition-all duration-300 ${chatMode === "simple" ? "bg-white/5 border border-white/10 text-white shadow-lg" : "border border-transparent hover:bg-white/[0.02] text-slate-400 hover:text-slate-200"}`}>
            <MessageSquare size={18} className={chatMode === "simple" ? "text-emerald-400" : "text-slate-500"} />
            <span className="text-sm font-medium">Global Knowledge</span>
          </button>

          <button onClick={() => uploadedFileName && setChatMode("pdf")} className={`group w-full p-4 rounded-xl flex items-center gap-4 transition-all duration-300 ${!uploadedFileName ? "opacity-40 cursor-not-allowed" : chatMode === "pdf" ? "bg-white/5 border border-white/10 text-white shadow-lg" : "border border-transparent hover:bg-white/[0.02] text-slate-400 hover:text-slate-200"}`}>
            <Database size={18} className={chatMode === "pdf" ? "text-emerald-400" : "text-slate-500"} />
            <span className="text-sm font-medium">RAG Document</span>
            {uploadedFileName && chatMode === "pdf" && <span className="ml-auto w-1.5 h-1.5 rounded-full bg-emerald-400 shadow-[0_0_10px_rgba(52,211,153,0.8)]"></span>}
          </button>
        </nav>

        {/* 📥 DATA INGESTION ZONE */}
        <div className="p-6">
          <p className="text-[11px] font-semibold text-slate-500 uppercase tracking-widest mb-3 px-2">Data Ingestion</p>
          <div className={`relative p-5 rounded-2xl border ${uploadedFileName ? "bg-emerald-950/20 border-emerald-500/30" : "bg-[#121214] border-white/5 hover:border-white/10"} transition-all duration-300`}>
            <label className="cursor-pointer flex flex-col items-center justify-center text-center group">
              {uploadedFileName ? (
                <>
                  <CheckCircle2 size={24} className="text-emerald-400 mb-2" />
                  <p className="text-xs font-semibold text-white truncate w-full">{uploadedFileName}</p>
                  <p className="text-[10px] text-emerald-500 mt-1 uppercase tracking-widest">Context Ready</p>
                </>
              ) : (
                <>
                  <div className="w-10 h-10 rounded-full bg-white/5 flex items-center justify-center mb-3 group-hover:bg-white/10 transition-colors">
                    <UploadCloud size={18} className="text-slate-400 group-hover:text-white" />
                  </div>
                  <p className="text-xs font-medium text-slate-300">Upload Report</p>
                  <p className="text-[10px] text-slate-500 mt-1">PDF max 10MB</p>
                </>
              )}
              <input type="file" accept=".pdf" className="hidden" onChange={handleFileUpload} />
            </label>
            {isUploading && (
              <div className="absolute inset-0 bg-[#0c0c0e]/80 backdrop-blur-sm rounded-2xl flex flex-col items-center justify-center border border-emerald-500/20">
                 <Loader2 className="animate-spin text-emerald-400 mb-2" size={20} />
                 <p className="text-[10px] text-emerald-400 tracking-widest uppercase">Processing...</p>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* ⚪ THE CHAT ARENA */}
      <div className="flex-1 flex flex-col relative bg-[#09090b]">
        
        {/* Subtle glowing orb in background */}
        <div className="absolute top-1/4 left-1/2 -translate-x-1/2 w-[600px] h-[600px] bg-emerald-900/10 rounded-full blur-[120px] pointer-events-none"></div>
        {/* Grid pattern */}
        <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-20 pointer-events-none mix-blend-overlay"></div>

        <header className="h-16 flex items-center justify-between px-8 border-b border-white/5 z-10 bg-[#09090b]/80 backdrop-blur-md">
          <h2 className="text-xs font-mono text-slate-400 flex items-center gap-2">
            <span className="text-emerald-500">~/</span>
            {chatMode === "simple" ? "models/global-sustainability-v1" : `models/rag-context/${uploadedFileName || "pending"}`}
          </h2>
        </header>

        {/* Message Stream */}
        <main className="flex-1 overflow-y-auto px-6 py-8 space-y-8 scroll-smooth pb-40 z-10 custom-scrollbar">
          <div className="max-w-3xl mx-auto space-y-8">
            {messages.length === 0 ? (
              <div className="h-[60vh] flex flex-col items-center justify-center text-center animate-in fade-in duration-1000">
                <div className="w-20 h-20 bg-white/5 border border-white/10 rounded-2xl flex items-center justify-center mb-6">
                  <Sparkles size={32} className="text-emerald-400" />
                </div>
                <h1 className="text-3xl font-bold text-white mb-4 tracking-tight">EcoBot Intelligence</h1>
                <p className="text-slate-400 text-sm max-w-md leading-relaxed">
                  Query the global sustainability database or upload a corporate PDF to initiate a targeted retrieval-augmented generation (RAG) analysis.
                </p>
              </div>
            ) : (
              messages.map((msg, idx) => (
                <div key={idx} className={`flex gap-5 ${msg.role === "user" ? "flex-row-reverse" : "flex-row"} animate-in slide-in-from-bottom-2 fade-in duration-300`}>
                  <div className={`w-8 h-8 rounded-lg flex items-center justify-center flex-shrink-0 border ${msg.role === "user" ? "bg-white/10 border-white/20 text-white" : "bg-emerald-500/20 border-emerald-500/30 text-emerald-400"}`}>
                    {msg.role === "user" ? <User size={14} /> : <Bot size={16} />}
                  </div>
                  <div className={`relative max-w-[80%] px-6 py-4 rounded-2xl text-[15px] leading-relaxed tracking-wide ${
                    msg.role === "user" 
                      ? "bg-emerald-600 text-white rounded-tr-sm shadow-lg shadow-emerald-900/20" 
                      : "bg-[#121214] text-slate-300 border border-white/5 rounded-tl-sm whitespace-pre-wrap"
                  }`}>
                    {msg.content}
                  </div>
                </div>
              ))
            )}
            {isLoading && (
              <div className="flex gap-5 items-center">
                <div className="w-8 h-8 rounded-lg bg-emerald-500/20 border border-emerald-500/30 flex items-center justify-center text-emerald-400">
                  <Bot size={16} />
                </div>
                <div className="bg-[#121214] border border-white/5 px-5 py-4 rounded-2xl rounded-tl-sm flex items-center gap-2">
                  <span className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-ping"></span>
                  <span className="text-xs font-mono text-emerald-500 uppercase tracking-widest">Computing</span>
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>
        </main>

        {/* ⌨️ FLOATING CONSOLE INPUT */}
        <div className="absolute bottom-8 left-0 w-full px-8 pointer-events-none z-20">
          <div className="max-w-3xl mx-auto w-full pointer-events-auto">
            <div className="bg-[#121214]/90 backdrop-blur-xl border border-white/10 p-2 rounded-2xl shadow-2xl">
              <form onSubmit={handleSendMessage} className="flex items-center gap-2">
                <div className="pl-4 text-emerald-500 font-mono text-lg">{">"}</div>
                <input
                  type="text"
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  placeholder={chatMode === "simple" ? "Enter query..." : "Query document context..."}
                  className="flex-1 bg-transparent border-none py-3 px-3 text-white placeholder-slate-600 focus:outline-none focus:ring-0 text-sm"
                />
                <button
                  type="submit"
                  disabled={isLoading || !input.trim()}
                  className="bg-white/10 text-white p-3 rounded-xl hover:bg-white/20 transition-all flex items-center justify-center disabled:opacity-30 disabled:hover:bg-white/10 border border-white/5"
                >
                  {isLoading ? <Loader2 className="animate-spin" size={18} /> : <Send size={18} />}
                </button>
              </form>
            </div>
            <p className="text-center text-[10px] text-slate-500 mt-3 font-mono">
              EcoBot Engine | Secure Connection
            </p>
          </div>
        </div>

      </div>
    </div>
  );
}